import pefile, capstone, struct, collections

PATH = r"C:\Users\el_en\AppData\Local\Temp\rebench-7psve4u4\artifacts\hard_license\license_probe.exe"
p = pefile.PE(PATH)
IB = p.OPTIONAL_HEADER.ImageBase
text = None
for s in p.sections:
    if s.Name.decode().rstrip('\0') == '.text':
        text = s
base = IB + text.VirtualAddress
code = text.get_data()
md = capstone.Cs(capstone.CS_ARCH_X86, capstone.CS_MODE_64)
md.detail = True

# targets of interest (RVAs from earlier string analysis)
targets = {
    0x140010330: "blob_current?",   # file 0xf530
    0x140010348: "blob_retired?",   # file 0xf548
    0x14001035c: "str_ACCEPT",
    0x140010368: "str_retired_flag",
    0x140010378: "str_RETIRED_ACCEPT",
    0x140010388: "str_REJECT",
}
xrefs = collections.defaultdict(list)
for ins in md.disasm(code, base):
    for op in ins.operands:
        if op.type == capstone.x86.X86_OP_MEM and op.mem.base == capstone.x86.X86_REG_RIP:
            ea = ins.address + ins.size + op.mem.disp
            if ea in targets:
                xrefs[ea].append((ins.address, ins.mnemonic, ins.op_str))

for t, name in targets.items():
    print(name, hex(t))
    for a, m, o in xrefs.get(t, []):
        print("   0x%x: %s %s" % (a, m, o))
